def check_following(response: str) -> bool:
    opens = [m.start() for m in re.finditer(r"<thought>", response)]
    closes = [m.start() for m in re.finditer(r"</thought>", response)]
    if len(opens) != 1 or len(closes) != 1 or opens[0] > closes[0]:
