import re
import json

def check_following(response: str) -> bool:
    text = response.strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL)
    if m:
        text = m.group(1).strip()
    percentages = None
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            cats = data.get("spending_categories") or (data.get("budget_analysis") or {}).get("spending_categories")
            if isinstance(cats, list):
                percentages = [float(str(c["percentage"]).rstrip("% ")) for c in cats if isinstance(c, dict) and "percentage" in c]
    except Exception:
        percentages = None
    if percentages is None:
        percentages = [float(x) for x in re.findall(r"\"percentage\"\s*:\s*\"?(-?\d+(?:\.\d+)?)", response)]
    if not percentages:
        return False
    return abs(sum(percentages) - 100) <= 0.5      # 允许小数舍入误差

