    def is_float(value):
        return isinstance(value, (int, float))

    def check_schema(obj):
        try:
            debt = obj["debt_reduction"]
            if not is_float(debt["total_debt"]):
                return False

            # Check debts list
            if not isinstance(debt["debts"], list) or len(debt["debts"]) == 0:
                return False
            for item in debt["debts"]:
                if not all(k in item for k in ["name", "amount", "interest_rate", "min_payment"]):
                    return False
                if not isinstance(item["name"], str):
                    return False
                if not is_float(item["amount"]) or not is_float(item["interest_rate"]) or not is_float(item["min_payment"]):
                    return False

            # Check payoff plans
