import json

def check_following(response: str):
    column = "Key Features"
    # 1) markdown 表格
    rows = [l for l in response.splitlines() if l.strip().startswith("|")]
    if len(rows) >= 2:
        header = [h.strip().lower() for h in rows[0].strip().strip("|").split("|")]
        if column.lower() in header:
            idx = header.index(column.lower())
            body = [r for r in rows[1:] if not re.fullmatch(r"\|[\s:\-|]+\|", r.strip())]
            if not body:
                return False
            for r in body:
                cells = [c.strip() for c in r.strip().strip("|").split("|")]
                if idx >= len(cells):
                    return False
                items = [x for x in re.split(r";|,|<br\s*/?>|\n|•", cells[idx]) if x.strip()]
                if not 1 <= len(items) <= 3:
                    return False
            return True
    # 2) JSON
    m = re.search(r"\{.*\}|\[.*\]", response, re.DOTALL)
    if m:
        try:
            data = json.loads(m.group(0))
            found = []
            def walk(o):
                if isinstance(o, dict):
                    for k, v in o.items():
                        if k.strip().lower() == column.lower():
                            found.append(v)
                        walk(v)
                elif isinstance(o, list):
                    for v in o:
                        walk(v)
            walk(data)
            if found:
                return all(isinstance(v, list) and 1 <= len(v) <= 3 or
                           isinstance(v, str) and 1 <= len([x for x in re.split(r";|,", v) if x.strip()]) <= 3
                           for v in found)
        except Exception:
            pass
    return None                           # 没有可识别的结构化输出 (结构本身由约束 3 负责) -> 不适用

