def check_following(response: str) -> bool:
    text = response.strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL)
    if m:
        text = m.group(1).strip()
    data = None
    try:
        data = json.loads(text)
    except Exception:
        m = re.search(r"\{.*\}", text, re.DOTALL)
        if m:
            try:
                data = json.loads(m.group(0))
            except Exception:
                data = None
    if isinstance(data, dict):
        keys = {k.strip().lower() for k in data}
        return {"topic", "search_queries", "focus_areas"} <= keys
    # 非 JSON: 三个字段名按顺序出现即可 (跨行)
    return bool(re.search(r"\btopic\b.*\bsearch_queries\b.*\bfocus_areas\b", response, re.IGNORECASE | re.DOTALL))

