def check_following(response: str) -> bool:
    try:
        # Attempt to compile the regex pattern using Rust regex syntax
        import regex  # Rust-like regex library in Python
        pattern = re.search(r"<regex>(.*?)</regex>", response, re.DOTALL)
        if pattern:
