        for m in re.finditer(rf'<invoke\s+name="{TOOL}"\s*>(.*?)</invoke>', response, re.DOTALL):
            if re.sub(r'<parameter\s+name="[^"]+"\s*>.*?</parameter>', "", m.group(1), flags=re.DOTALL).strip():
                return False
    return True

