    if not calls:
        return None                       # 没有用 replace_in_file -> 不适用
    paths = [re.search(r"<path>(.*?)</path>", c, re.DOTALL) for c in calls]
    paths = [p.group(1).strip() for p in paths if p]
    if len(paths) != len(set(paths)):
        return False                      # 同一文件拆成了多个 replace_in_file 调用
    n_blocks = sum(len(re.findall(r"<<<<<<< SEARCH", c)) for c in calls)
    if n_blocks >= 2:
        return True                       # 多个块堆叠在一次调用里
    return None                           # 只有一处修改, 看不出是否"需要多处修改" -> 不适用

