def check_following(response: str):
    blocks = re.findall(r"<browser_action>(.*?)</browser_action>", response, re.DOTALL)
    if not blocks:
        return None                       # 没有 browser_action -> 不适用
    valid = {"launch", "click", "type", "scroll_down", "scroll_up", "close"}
    for b in blocks:
        a = re.search(r"<action>(.*?)</action>", b, re.DOTALL)
        if not a or a.group(1).strip() not in valid:
            return False
        if a.group(1).strip() == "launch":
            u = re.search(r"<url>(.*?)</url>", b, re.DOTALL)
            if not u or not re.match(r"^(https?://|file://)\S+$", u.group(1).strip()):
                return False              # 启动浏览器必须给出 URL
    return True

