def check_following(response: str):
    m = re.search(r"<attempt_completion>(.*?)</attempt_completion>", response, re.DOTALL)
    if not m:
        return None                       # 没有 attempt_completion -> 不适用
    cmd = re.search(r"<command>(.*?)</command>", m.group(1), re.DOTALL)
    if not cmd or not cmd.group(1).strip():
