        # 2. 参数: 必填齐且非空, 没有未定义的参数, 枚举值合法
        for p in REQUIRED:
            if p not in params or not str(params[p]).strip():
                return False
        if set(params) - set(REQUIRED) - set(OPTIONAL):
            return False
        for p, allowed in ENUM.items():
            if p in params and str(params[p]).strip() not in allowed:
                return False
