                ch = text[j]
                if in_str:
                    if esc: esc = False
                    elif ch == "\\": esc = True
                    elif ch == '"': in_str = False
                    continue
                if ch == '"': in_str = True
                elif ch == "{": depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        frag = text[i:j + 1]
                        try:
                            obj = json.loads(frag); return (obj if isinstance(obj, dict) else None), j + 1
                        except Exception:
                            return {k: "" for k in re.findall(r'"([A-Za-z_]\w*)"\s*:', frag)}, j + 1
            return None, i
