            body = m.group(3)
            if name == "lov-write" and body is not None and body.strip():
                attrs["content"] = body
            if name == "lov-add-dependency" and body is not None and body.strip():
                attrs["package"] = body.strip()
            calls.append((name, attrs, "lov"))
        # 6) Gemma 原生: <|tool_call>call:NAME{k:<|"|>v<|"|>,k2:"v",k3:true}<tool_call|>  (也接受没有外层标记的 call:NAME{...})
