        for m in re.finditer(r'(?:<\|tool_call>)?\bcall:([A-Za-z_][\w.-]*)\{(.*?)\}(?:<tool_call\|>|\s*$|\n)', response, re.DOTALL):
            body = m.group(2); params = {}
            keys = list(re.finditer(r'(?:^|,)\s*([A-Za-z_]\w*)\s*:\s*', body))
