                    elif ch == "\\": esc = True
                    elif ch == '"': in_str = False
                    continue
                if ch == '"': in_str = True
                elif ch == "{": depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        frag = text[i:j + 1]
                        try:
                            obj = json.loads(frag); return (obj if isinstance(obj, dict) else None), j + 1
                        except Exception:
