import re
import json
import difflib

def check_following(response: str):
    TOOLS = ['create_new_jupyter_notebook', 'create_new_workspace', 'fetch_webpage', 'file_search', 'get_changed_files', 'get_errors', 'get_project_setup_info', 'get_terminal_output', 'get_vscode_api', 'grep_search', 'insert_edit_into_file', 'install_extension', 'list_code_usages', 'list_dir', 'read_file', 'run_in_terminal', 'semantic_search', 'test_search']

    def _parse_calls(response):
        """返回 [(name, params_dict, convention)]。识别: invoke / function= / json / cline-xml / lov / python"""
        calls = []
        def _obj_at(text, i):
            """text[i] == '{' -> (dict|None, end_index)  花括号配对后 json.loads; 失败则退化为抽 key"""
            depth = 0; in_str = False; esc = False
            for j in range(i, min(len(text), i + 20000)):
                ch = text[j]
                if in_str:
                    if esc: esc = False
                    elif ch == "\\": esc = True
                    elif ch == '"': in_str = False
                    continue
                if ch == '"': in_str = True
                elif ch == "{": depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        frag = text[i:j + 1]
                        try:
                            obj = json.loads(frag); return (obj if isinstance(obj, dict) else None), j + 1
                        except Exception:
                            return {k: "" for k in re.findall(r'"([A-Za-z_]\w*)"\s*:', frag)}, j + 1
            return None, i
        def _args_of(obj):
            """从 function-calling 风格对象里取参数 dict: arguments/parameters/input/args 优先, 否则取 name 的兄弟键"""
            if not isinstance(obj, dict): return {}
            for k in ("arguments", "parameters", "input", "args", "params"):
                if isinstance(obj.get(k), dict): return obj[k]
                if isinstance(obj.get(k), str) and obj[k].strip().startswith("{"):
                    o, _ = _obj_at(obj[k].strip(), 0); return o or {}
            return {k: v for k, v in obj.items() if k not in ("name", "tool", "function", "description", "type", "id", "recipient")}
        # 1) <invoke name="X"> <parameter name="p">v</parameter> </invoke>   (body 也可能直接是 JSON)
        for m in re.finditer(r'<invoke\s+name="([^"]+)"\s*>(.*?)</invoke>', response, re.DOTALL):
            params = dict(re.findall(r'<parameter\s+name="([^"]+)"\s*>(.*?)</parameter>', m.group(2), re.DOTALL))
            if not params and m.group(2).strip().startswith("{"):
                o, _ = _obj_at(m.group(2).strip(), 0); params = o or {}
            calls.append((m.group(1).strip(), params, "invoke"))
        # 1b) <function name="X"><param name="p">v</param></function>  /  <tool_call name="X">{json}  /  <tool name="X">
        for m in re.finditer(r'<(?:function|tool_call|tool|function_call)\s+name="([^"]+)"\s*>(.*?)(?:</(?:function|tool_call|tool|function_call)>|$)', response, re.DOTALL):
            body = m.group(2)
            params = dict(re.findall(r'<param(?:eter)?\s+name="([^"]+)"\s*>(.*?)</param(?:eter)?>', body, re.DOTALL))
            if not params and body.strip().startswith("{"):
                o, _ = _obj_at(body.strip(), 0); params = o or {}
            calls.append((m.group(1).strip(), params, "xml-attr"))
        # 2) <function=X> <parameter=p>v</parameter> </function>
        for m in re.finditer(r'<function=([^>\s]+)\s*>(.*?)</function>', response, re.DOTALL):
            params = dict(re.findall(r'<parameter=([^>\s]+)\s*>(.*?)</parameter>', m.group(2), re.DOTALL))
            calls.append((m.group(1).strip(), params, "function="))
        # 3) JSON 对象里带 "name"/"tool"/"function": "X"  -> 参数取 arguments/parameters/..., 否则取兄弟键
        for m in re.finditer(r'"(?:name|tool|function|tool_name)"\s*:\s*"([A-Za-z_][\w.-]*)"', response):
            i = response.rfind("{", 0, m.start())
            if i < 0: continue
            obj, _ = _obj_at(response, i)
            if isinstance(obj, dict) and isinstance(obj.get("function"), dict):   # {"type":"function","function":{"name":..,"arguments":..}}
                obj = obj["function"]
            calls.append((m.group(1), _args_of(obj), "json"))
        # 3b) Harmony (gpt-oss): "to=X <|constrain|>json\n{...}"  /  "to=X<|channel|>analysis code\n{...}"  /  "commentary to=functions.X ..."
        for m in re.finditer(r'\bto=(?:functions\.)?([A-Za-z_][\w.-]*)', response):
            j = response.find("{", m.end(), m.end() + 300)
            if j < 0: continue
            obj, _ = _obj_at(response, j)
            calls.append((m.group(1), obj or {}, "harmony"))
        # 4) Cline 式 XML: <X> <p>v</p> ... </X>  (块内只能是参数标签)
        for m in re.finditer(r'<([A-Za-z_][\w-]*)>\s*((?:<[\w-]+>.*?</[\w-]+>\s*)*)</\1>', response, re.DOTALL):
            name = m.group(1)
            if name in ("thinking", "think", "tool_call", "function_calls", "invoke", "parameter", "function", "tool_use", "tool_calls"):
                continue
            params = dict(re.findall(r'<([\w-]+)>(.*?)</\1>', m.group(2), re.DOTALL))
            calls.append((name, params, "cline-xml"))
        # 4b) <X>{json}</X>  (Ministral 等)
        for m in re.finditer(r'<([A-Za-z_][\w-]*)>\s*(\{.*?\})\s*</\1>', response, re.DOTALL):
            if m.group(1) in ("tool_call", "function_calls", "invoke", "parameter", "function", "tool_use", "tool_calls", "arguments", "parameters"):
                continue
            obj, _ = _obj_at(m.group(2), 0)
            calls.append((m.group(1), _args_of(obj) if obj and ("name" in obj or "arguments" in obj) else (obj or {}), "xml-json"))
        # 5) Lovable 属性标签: <lov-write file_path="x">body</lov-write> / <lov-rename a="" b="" /> / <lov-add-dependency>pkg@ver</lov-add-dependency>
        for m in re.finditer(r'<(lov-write|lov-rename|lov-delete|lov-add-dependency)((?:\s+[\w-]+="[^"]*")*)\s*(?:/>|>(.*?)</\1>)', response, re.DOTALL):
            name = m.group(1); attrs = dict(re.findall(r'([\w-]+)="([^"]*)"', m.group(2) or ''))
            body = m.group(3)
            if name == "lov-write" and body is not None and body.strip():
                attrs["content"] = body
            if name == "lov-add-dependency" and body is not None and body.strip():
                attrs["package"] = body.strip()
            calls.append((name, attrs, "lov"))
        # 6) Gemma 原生: <|tool_call>call:NAME{k:<|"|>v<|"|>,k2:"v",k3:true}<tool_call|>  (也接受没有外层标记的 call:NAME{...})
        for m in re.finditer(r'(?:<\|tool_call>)?\bcall:([A-Za-z_][\w.-]*)\{(.*?)\}(?:<tool_call\|>|\s*$|\n)', response, re.DOTALL):
            body = m.group(2); params = {}
            keys = list(re.finditer(r'(?:^|,)\s*([A-Za-z_]\w*)\s*:\s*', body))
            for i, km in enumerate(keys):
                end = keys[i + 1].start() if i + 1 < len(keys) else len(body)
                val = body[km.end():end].strip().rstrip(',').strip()
                val = re.sub(r'^<\|"\|>|<\|"\|>$', '', val).strip().strip('"').strip("'")
                params[km.group(1)] = val
            calls.append((m.group(1).strip(), params, "gemma-native"))
        # 7) python / JS 风格调用 X(k=v, ...) 或 X({k: v})  全文搜索, 但必须至少带一个具名参数 (避免把散文里的 foo() 当调用); 去掉 default_api. 等前缀
        for m in re.finditer(r'\b([A-Za-z_]\w*)\s*\(\s*(\{?[^()]*\}?)\s*\)', response):
            inner = m.group(2).strip().strip("{}")
            kms = list(re.finditer(r'(?:^|,)\s*["\']?([A-Za-z_]\w*)["\']?\s*[=:]\s*', inner))
            if not kms: continue
            params = {}
            for i, km in enumerate(kms):
                end = kms[i + 1].start() if i + 1 < len(kms) else len(inner)
                params[km.group(1)] = inner[km.end():end].strip().rstrip(",").strip().strip('"').strip("'")
            calls.append((m.group(1), params, "python"))
        return calls

    def _norm(s):
        return re.sub(r'[^a-z0-9]', '', s.lower()).rstrip('s')

    def _is_near(name, target):
        if name == target:
            return False
        a, b = _norm(name), _norm(target)
        return a == b or difflib.SequenceMatcher(None, a, b).ratio() >= 0.8

    # 只看明确的工具调用写法 (invoke / function= / 带参数对象的 json), 避免把普通 XML/JSON/代码当成工具调用
    calls = [(n, p, c) for n, p, c in _parse_calls(response)
             if c in ("invoke", "function=", "gemma-native", "xml-attr", "harmony", "xml-json") or (c == "json" and p)]
    if not calls:
        return None                       # 没有工具调用 -> 不适用
    for n, _p, _c in calls:
        if n in TOOLS:
            continue
        if any(_is_near(n, t) for t in TOOLS):
            continue                      # 近似名: 由对应工具那条约束扣分, 这里不重复扣
        return False                      # 调用了工具表里不存在的工具
    return True

