            if name in ("thinking", "think", "tool_call", "function_calls", "invoke", "parameter", "function", "tool_use", "tool_calls"):
                continue
            params = dict(re.findall(r'<([\w-]+)>(.*?)</\1>', m.group(2), re.DOTALL))
            calls.append((name, params, "cline-xml"))
        # 4b) <X>{json}</X>  (Ministral 等)
        for m in re.finditer(r'<([A-Za-z_][\w-]*)>\s*(\{.*?\})\s*</\1>', response, re.DOTALL):
            if m.group(1) in ("tool_call", "function_calls", "invoke", "parameter", "function", "tool_use", "tool_calls", "arguments", "parameters"):
                continue
            obj, _ = _obj_at(m.group(2), 0)
            calls.append((m.group(1), _args_of(obj) if obj and ("name" in obj or "arguments" in obj) else (obj or {}), "xml-json"))
        # 5) Lovable 属性标签: <lov-write file_path="x">body</lov-write> / <lov-rename a="" b="" /> / <lov-add-dependency>pkg@ver</lov-add-dependency>
        for m in re.finditer(r'<(lov-write|lov-rename|lov-delete|lov-add-dependency)((?:\s+[\w-]+="[^"]*")*)\s*(?:/>|>(.*?)</\1>)', response, re.DOTALL):
            name = m.group(1); attrs = dict(re.findall(r'([\w-]+)="([^"]*)"', m.group(2) or ''))
            body = m.group(3)
            if name == "lov-write" and body is not None and body.strip():
                attrs["content"] = body
            if name == "lov-add-dependency" and body is not None and body.strip():
                attrs["package"] = body.strip()
            calls.append((name, attrs, "lov"))
        # 6) Gemma 原生: <|tool_call>call:NAME{k:<|"|>v<|"|>,k2:"v",k3:true}<tool_call|>  (也接受没有外层标记的 call:NAME{...})
        for m in re.finditer(r'(?:<\|tool_call>)?\bcall:([A-Za-z_][\w.-]*)\{(.*?)\}(?:<tool_call\|>|\s*$|\n)', response, re.DOTALL):
            body = m.group(2); params = {}
            keys = list(re.finditer(r'(?:^|,)\s*([A-Za-z_]\w*)\s*:\s*', body))
            for i, km in enumerate(keys):
                end = keys[i + 1].start() if i + 1 < len(keys) else len(body)
                val = body[km.end():end].strip().rstrip(',').strip()
                val = re.sub(r'^<\|"\|>|<\|"\|>$', '', val).strip().strip('"').strip("'")
                params[km.group(1)] = val
            calls.append((m.group(1).strip(), params, "gemma-native"))
        # 7) python / JS 风格调用 X(k=v, ...) 或 X({k: v})  全文搜索, 但必须至少带一个具名参数 (避免把散文里的 foo() 当调用); 去掉 default_api. 等前缀
        for m in re.finditer(r'\b([A-Za-z_]\w*)\s*\(\s*(\{?[^()]*\}?)\s*\)', response):
            inner = m.group(2).strip().strip("{}")
            kms = list(re.finditer(r'(?:^|,)\s*["\']?([A-Za-z_]\w*)["\']?\s*[=:]\s*', inner))
            if not kms: continue
            params = {}
            for i, km in enumerate(kms):
                end = kms[i + 1].start() if i + 1 < len(kms) else len(inner)
                params[km.group(1)] = inner[km.end():end].strip().rstrip(",").strip().strip('"').strip("'")
            calls.append((m.group(1), params, "python"))
        return calls

    def _norm(s):
        return re.sub(r'[^a-z0-9]', '', s.lower()).rstrip('s')

    def _is_near(name, target):
        if name == target:
            return False
        a, b = _norm(name), _norm(target)
        return a == b or difflib.SequenceMatcher(None, a, b).ratio() >= 0.8

    # code 预筛: 明确用正确名字调用了本工具 -> 条件直接成立, 跳过 llm 判断
    return any(n == TOOL for n, _, _ in _parse_calls(response))

