            return False
        a, b = _norm(name), _norm(target)
        return a == b or difflib.SequenceMatcher(None, a, b).ratio() >= 0.8

    # 条件已成立 (code 预筛命中, 或 llm 判定模型有使用本工具的需求/倾向)
    calls = _parse_calls(response)
    mine = [(p, c) for n, p, c in calls if n == TOOL]
