                if isinstance(obj.get(k), dict): return obj[k]
                if isinstance(obj.get(k), str) and obj[k].strip().startswith("{"):
                    o, _ = _obj_at(obj[k].strip(), 0); return o or {}
            return {k: v for k, v in obj.items() if k not in ("name", "tool", "function", "description", "type", "id", "recipient")}
        # 1) <invoke name="X"> <parameter name="p">v</parameter> </invoke>   (body 也可能直接是 JSON)
        for m in re.finditer(r'<invoke\s+name="([^"]+)"\s*>(.*?)</invoke>', response, re.DOTALL):
