'''
首先，我需要编写一个C语言程序来计算从出生到现在的心跳总数。程序需要区分闰年和非闰年，因为闰年有366天，非闰年有365天。假设平均每分钟心跳次数为72次，我们可以通过以下步骤计算：
1. 计算从出生年份到当前年份的总天数。
2. 根据闰年和非闰年分别计算天数。
3. 计算总心跳数 = 总天数 × 24小时 × 60分钟 × 72次/分钟。
4. 输出结果。
'''

# 编写C语言程序
c_code = """
#include <stdio.h>

// 判断是否为闰年
int is_leap_year(int year) {
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        return 1; // 是闰年
    } else {
        return 0; // 不是闰年
    }
}

// 计算从出生到现在的心跳总数
long long calculate_heartbeats(int birth_year, int current_year) {
    long long total_days = 0;
    for (int year = birth_year; year < current_year; year++) {
        if (is_leap_year(year)) {
            total_days += 366; // 闰年
        } else {
            total_days += 365; // 非闰年
        }
    }
    // 计算总心跳数：总天数 × 24小时 × 60分钟 × 72次/分钟
    long long total_heartbeats = total_days * 24 * 60 * 72;
    return total_heartbeats;
}

int main() {
    int birth_year, current_year;

    // 输入出生年份和当前年份
    printf("请输入您的出生年份: ");
    scanf("%d", &birth_year);
    printf("请输入当前年份: ");
    scanf("%d", &current_year);

    // 计算心跳总数
    long long heartbeats = calculate_heartbeats(birth_year, current_year);

    // 输出结果
    printf("从出生到现在，您的心跳总数约为: %lld 次\\n", heartbeats);

    return 0;
}
"""

# 将C语言代码保存为文件
with open("/mnt/data/heartbeat_calculator.c", "w") as file:
    file.write(c_code)

print("C语言程序已生成并保存为 /mnt/data/heartbeat_calculator.c")

